import XCTest
final class ProbeTests:XCTestCase {
 func tap(_ app:XCUIApplication,_ name:String){let q=app.buttons.matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);if q.count==1{q.firstMatch.tap();return};guard let b=q.allElementsBoundByIndex.first(where:{$0.isHittable})else{XCTFail("No hittable button "+name);return};b.tap()}
 func type(_ field:XCUIElement,_ value:String){field.tap();for c in value{field.typeText(String(c));Thread.sleep(forTimeInterval:0.15)}}
 func testJ010CancelledGroupStillReceivesAndSends() throws {
 continueAfterFailure=false
 let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.launch();tap(app,"Inbox, tab, 4 of 5");let group=app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","QA J010 insufficient table")).firstMatch;XCTAssertTrue(group.waitForExistence(timeout:15),app.debugDescription);print("QA_NATIVE95_INBOX_NOTIFICATION_ENTRY_INSPECTION\n"+app.debugDescription);let inbox=XCTAttachment(screenshot:app.screenshot());inbox.name="native95-inbox-notification-entry-absent";inbox.lifetime = .keepAlways;add(inbox);group.tap();XCTAssertTrue(app.staticTexts["QA J010 host: the cancelled table group remains available."].waitForExistence(timeout:15),app.debugDescription);let msg=app.textViews.matching(NSPredicate(format:"label BEGINSWITH %@","Message")).firstMatch;XCTAssertTrue(msg.waitForExistence(timeout:10));type(msg,"QA95");let send=app.buttons["Send"],keyboard=app.keyboards.firstMatch;print("QA_NATIVE95_GEOMETRY keyboard=\(keyboard.frame) message=\(msg.frame) send=\(send.frame) hittable=\(send.isHittable)\n"+app.debugDescription);let k=XCTAttachment(screenshot:app.screenshot());k.name="native95-chat-keyboard-send-geometry";k.lifetime = .keepAlways;add(k);XCTAssertTrue(send.isHittable,"Chat Send must physically be reachable while typing");XCTAssertLessThanOrEqual(send.frame.maxY,keyboard.frame.minY+1);tap(app,"Send");XCTAssertTrue(app.staticTexts["QA95"].waitForExistence(timeout:15),app.debugDescription);print("QA_NATIVE95_CANCELLED_GROUP_RECEIVE_AND_SEND\n"+app.debugDescription);let a=XCTAttachment(screenshot:app.screenshot());a.name="native95-cancelled-group-receive-send";a.lifetime = .keepAlways;add(a)
 }
}
